with filtered as (select *, case when is_remote then 'Yes' else 'No' end as is_remote_label, coalesce(job_title, 'OTHER') as job_title_filled from employees where hire_date < '2025-01-27') select p.location, src.level, count(*) as cnt, max(src.salary) as max_salary from filtered src inner join departments p on src.dept_id = p.id group by grouping sets ((p.location, src.level), (p.location))
